import argparse, re, sys
from collections import Counter

p = argparse.ArgumentParser(description="Find brute-force sources in an SSH log")
p.add_argument("logfile")
p.add_argument("--threshold", type=int, default=3)
args = p.parse_args()

pattern = re.compile(r"Failed password .* from (\S+)")
counts = Counter()
try:
    with open(args.logfile, errors="replace") as f:
        for line in f:
            m = pattern.search(line)
            if m:
                counts[m.group(1)] += 1
except FileNotFoundError:
    sys.exit(f"No such file: {args.logfile}")

for ip, n in counts.most_common():
    if n >= args.threshold:
        print(f"{ip}: {n} failed logins")
